with exploded as (select id, host, level, status_code, attr_key, v from app_logs lateral view explode(context) t as attr_key, v) select attr_key, host, count(case when attr_key = 'region' then 1 end) as region_count, size(collect_set(level)) as num_levels, round(avg(status_code), 2) as avg_status_code, size(collect_set(attr_key)) as num_attr_keys, count(*) as num_rows from exploded group by attr_key, host having num_rows > 1;
